cat > src/openingHours.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { OpeningHoursError, parseOpeningHours, type OpeningHoursErrorCode, type WeeklyHours } from "./openingHours";

function week(hours: Partial<WeeklyHours>): WeeklyHours {
  return { Mo: [], Tu: [], We: [], Th: [], Fr: [], Sa: [], Su: [], ...hours };
}

function expectError(text: string, code: OpeningHoursErrorCode, column: number) {
  let caught: unknown;
  try {
    parseOpeningHours(text);
  } catch (error) {
    caught = error;
  }
  expect(caught).toBeInstanceOf(OpeningHoursError);
  const error = caught as OpeningHoursError;
  expect({ code: error.code, column: error.column }).toEqual({ code, column });
}

test("errors report the column in their message", () => {
  const error = new OpeningHoursError("UNKNOWN_DAY", 4, 'Unknown day "Fx"');
  expect(error).toBeInstanceOf(Error);
  expect(error.code).toBe("UNKNOWN_DAY");
  expect(error.column).toBe(4);
  expect(error.message).toBe('Unknown day "Fx" (column 4)');
});

test("one day with one range gives that range and all other days closed", () => {
  expect(parseOpeningHours("Mo 08:00-12:00")).toEqual(week({ Mo: [{ from: "08:00", to: "12:00" }] }));
});
EOF
.claude/skills/tdd-deep-modules/scripts/tdd-step red "one day with one range" 2>&1 | tail -5; git log --oneline -1

